<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useDisplay } from 'vuetify'
import { deliveriesApi } from '@/api/deliveries'
import { salesOrdersApi } from '@/api/salesOrders'
import { useOrganizationContextStore } from '@/stores/organizationContext'
import { useApiError } from '@/composables/useApiError'
import { usePermission } from '@/composables/usePermission'
import AppMobileRecordCard from '@/components/AppMobileRecordCard.vue'
import type { Delivery, DeliveryAudit } from '@/types/deliveries'
import type { SalesOrder } from '@/types/salesOrders'
const {t}=useI18n();const {mdAndUp}=useDisplay();const org=useOrganizationContextStore();const {can}=usePermission();const error=useApiError();const rows=ref<Delivery[]>([]),orders=ref<SalesOrder[]>([]),loading=ref(false),saving=ref(false),editor=ref(false),selected=ref<Delivery|null>(null),audits=ref<DeliveryAudit[]>([]),notice=ref(''),source=ref<SalesOrder|null>(null)
const form=reactive({companyId:null as number|null,branchId:null as number|null,notes:'',lines:[] as Array<{orderLineId:number;quantity:number;ordered:number;reserved:number;previous:number;backordered:number;name:string}>})
const canSave=computed(()=>!!form.companyId&&!!form.branchId&&form.lines.length>0&&form.lines.every(l=>l.quantity>0&&l.quantity<=l.reserved-l.previous))
async function load(){if(!org.companyId||!org.branchId)return;loading.value=true;try{[rows.value,orders.value]=await Promise.all([deliveriesApi.list(org.companyId,org.branchId),salesOrdersApi.list(org.companyId,org.branchId)]);orders.value=orders.value.filter(o=>o.status==='CONFIRMED')}catch(e){error.set(e)}finally{loading.value=false}}
function open(order:SalesOrder){source.value=order;Object.assign(form,{companyId:order.companyId,branchId:order.branchId,notes:'',lines:order.lines.map(l=>({orderLineId:l.id,quantity:0,ordered:l.quantity,reserved:l.reservedQuantity,previous:0,backordered:l.backorderedQuantity,name:l.name})).filter(l=>l.reserved>l.previous)});editor.value=true}
async function save(){if(!source.value||!canSave.value)return;saving.value=true;try{await deliveriesApi.create(source.value.id,{companyId:form.companyId!,branchId:form.branchId!,notes:form.notes||undefined,lines:form.lines.map(l=>({orderLineId:l.orderLineId,quantity:l.quantity}))});editor.value=false;notice.value=t('salesDocuments.saved');await load()}catch(e){error.set(e)}finally{saving.value=false}}
async function show(row:Delivery){try{const [d,a]=await Promise.all([deliveriesApi.get(row.id),deliveriesApi.audit(row.id)]);selected.value=d;audits.value=a}catch(e){error.set(e)}}
async function action(kind:'confirm'|'cancel'){if(!selected.value)return;saving.value=true;try{selected.value=kind==='confirm'?await deliveriesApi.confirm(selected.value.id):await deliveriesApi.cancel(selected.value.id);await load()}catch(e){error.set(e)}finally{saving.value=false}}
onMounted(async()=>{if(!org.context)await org.refresh();await load()})
</script>
<template><section><v-alert v-if="!org.companyId||!org.branchId" type="warning" variant="tonal">{{t('salesDocuments.scopeRequired')}}</v-alert><v-alert v-if="notice" type="success" variant="tonal" class="mb-3">{{notice}}</v-alert><v-alert v-if="error.message.value" type="error" variant="tonal" class="mb-3">{{error.message.value}}</v-alert><v-card rounded="xl"><v-card-title>{{t('salesOrders.deliveries')}}</v-card-title><v-card-text><v-data-table v-if="mdAndUp" :headers="[{title:'',key:'number'},{title:t('salesDocuments.status'),key:'status'},{title:'',key:'actions'}]" :items="rows" :loading="loading"><template #item.status="{item}"><v-chip>{{item.status}}</v-chip></template><template #item.actions="{item}"><v-btn icon="mdi-eye-outline" variant="text" @click="show(item)"/></template></v-data-table><div v-else class="d-grid ga-3"><AppMobileRecordCard v-for="row in rows" :key="row.id" :label="row.number" @open="show(row)"><div>{{row.status}}</div></AppMobileRecordCard></div><v-divider class="my-4"/><v-list density="compact"><v-list-subheader>{{t('salesOrders.title')}}</v-list-subheader><v-list-item v-for="o in orders" :key="o.id" :title="o.number"><template #append><v-btn v-if="can('sales:create')" size="small" @click="open(o)">{{t('salesOrders.newDelivery')}}</v-btn></template></v-list-item></v-list></v-card-text></v-card><v-dialog v-model="editor" :fullscreen="!mdAndUp" max-width="760"><v-card><v-card-title>{{t('salesOrders.newDelivery')}}</v-card-title><v-card-text><v-textarea v-model="form.notes"/><v-card v-for="line in form.lines" :key="line.orderLineId" variant="outlined" class="pa-3 mb-3"><div class="d-flex justify-space-between mb-2"><span>{{line.name}}</span><small>{{t('salesOrders.ordered')}}: {{line.ordered}} · {{t('salesOrders.reserved')}}: {{line.reserved}} · {{t('salesOrders.previouslyDelivered')}}: {{line.previous}} · {{t('salesOrders.backordered')}}: {{line.backordered}}</small></div><v-text-field v-model.number="line.quantity" type="number" min="0.001" :max="line.reserved-line.previous" :label="t('salesOrders.deliveryQuantity')"/></v-card></v-card-text><v-card-actions><v-btn @click="editor=false">{{t('common.cancel')}}</v-btn><v-spacer/><v-btn color="primary" :disabled="!canSave" :loading="saving" @click="save">{{t('common.save')}}</v-btn></v-card-actions></v-card></v-dialog><v-dialog :model-value="!!selected" @update:model-value="v=>{if(!v)selected=null}" max-width="760"><v-card v-if="selected"><v-card-title>{{selected.number}} · {{selected.status}}</v-card-title><v-card-text><div v-for="line in selected.lines" :key="line.id" class="py-2">{{line.name}} · {{t('salesOrders.deliveryQuantity')}}: {{line.deliveryQuantity}} · {{t('salesOrders.deliverable')}}: {{line.remainingQuantity}}</div><v-divider class="my-3"/><v-list density="compact"><v-list-item v-for="audit in audits" :key="audit.id" :title="audit.action" :subtitle="audit.occurredAt"/></v-list></v-card-text><v-card-actions><v-btn v-if="selected.status==='DRAFT'&&can('sales:confirm')" color="primary" :loading="saving" @click="action('confirm')">{{t('salesOrders.confirm')}}</v-btn><v-btn v-if="selected.status==='DRAFT'&&can('sales:edit')" color="error" @click="action('cancel')">{{t('salesDocuments.cancel')}}</v-btn></v-card-actions></v-card></v-dialog></section></template>
